//Four-leaf clover
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // Normalize the fragment coordinates to a range of [-aspectRatio, aspectRatio] and [-1, 1]
    // where the y-axis is scaled based on the screen resolution.
    vec2 uv = (2.0 * fragCoord - iResolution.xy) / iResolution.y;

    // Calculate the distance (radius) from the center of the screen to the current fragment.
    // Multiplying by a higher value (0.5 here) shrinks the radial pattern.
    float r = length(uv) * 0.5;

    // Calculate the polar angle (theta) in radians using atan.
    // Subtracting iTime causes the pattern to rotate clockwise over time.
    float theta = atan(uv.x, uv.y) - iTime;

    // Generate a periodic function based on theta.
    // Combining cos and sin creates an interference pattern.
    // The abs function ensures all values are positive, forming symmetric bands.
    float f = abs(cos(theta * 1.) * sin(theta * 1.)) * +0.6;

    // Interpolate between two colors (white and green).
    vec3 color = mix(vec3(1.0f), vec3(0.0, 1.0, 0.0), vec3(1.0 - smoothstep(f, f + 0.03, r)));

    fragColor = vec4(color, 1.0f);
}
